/** Tom liste = ingen filter = alle typer på aksen. Fuld liste = samme som ingen filter → normalisér til []. */ function normalizePushIncludeFilter(ids, allIds) {
    if (allIds.length === 0) return [];
    const picked = [
        ...new Set(ids)
    ].filter((id)=>allIds.includes(id));
    if (picked.length === 0) return [];
    if (picked.length === allIds.length && allIds.every((id)=>picked.includes(id))) {
        return [];
    }
    return picked;
}
